def write_png(canvas: Canvas, path: Path) -> dict[str, object]:
    path.parent.mkdir(parents=True, exist_ok=True)
    data = canvas.png_bytes()
    path.write_bytes(data)
    return {
        "path": path.name,
        "sha256": hashlib.sha256(data).hexdigest(),
        "width": canvas.width,
        "height": canvas.height,
    }
